-- ════════════════════════════════════════════════════════════════
-- Migration 373: Inventory System Enhancements
-- ════════════════════════════════════════════════════════════════
-- Implements 6 enhancement areas requested for the inventory system:
--
--   Gap 1: Dual-ledger consumption (Central = separate stock model)
--          - Adds uinv_replenishment_pulls table to track auto-generated
--            central→dept transfer requests triggered by dept consumption.
--          - Adds generate_replenishment_pulls_for_dept() function that
--            creates transfer requests when dept stock drops below par.
--
--   Gap 2: Manual par overrides (temporary tier with auto-revert)
--          - Adds uinv_manual_par_overrides table.
--          - Adds effective_par_level() function that resolves the
--            effective par (manual override > dynamic > standard).
--
--   Gap 3: Procurement auto-trigger (low central stock → purchase req)
--          - Adds generate_procurement_requisitions() function that
--            scans UINV-ST-MAIN for low stock and creates proc_requisitions.
--          - Fixes proc_requisitions.id / proc_requisition_lines.id defaults.
--
--   Gap 4: Finance journal auto-posting (COGS/inventory valuation/shrinkage)
--          - Adds inventory asset + shrinkage GL accounts to chart of accounts.
--          - Adds uinv_journal_posting_log table to prevent duplicate postings.
--          - Adds post_inventory_journal() function for COGS/valuation/shrinkage.
--
--   Gap 5: Inter-departmental stock borrowing (temporary loans + approval)
--          - Adds uinv_dept_borrows table with approval workflow + return.
--
--   Gap 6: POS → unified inventory dual-write
--          - Adds pos_outlets.default_store_id + ingredients.uinv_item_id.
--          - Replaces deduct_outlet_inventory() with a corrected version
--            that uses real tables (recipes/recipe_lines/ingredients) AND
--            dual-writes to uinv_stock_balances + uinv_stock_ledger.
-- ════════════════════════════════════════════════════════════════

-- ════════════════════════════════════════════════════════════════
-- FIX: proc_requisitions.id / proc_requisition_lines.id defaults
-- (Migration 345 left these without a default → inserts fail)
-- ════════════════════════════════════════════════════════════════
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_name = 'proc_requisitions' AND column_name = 'id'
      AND column_default IS NULL
  ) THEN
    ALTER TABLE public.proc_requisitions
      ALTER COLUMN id SET DEFAULT gen_random_uuid()::text;
  END IF;
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_name = 'proc_requisition_lines' AND column_name = 'id'
      AND column_default IS NULL
  ) THEN
    ALTER TABLE public.proc_requisition_lines
      ALTER COLUMN id SET DEFAULT gen_random_uuid()::text;
  END IF;
END $$;

-- ════════════════════════════════════════════════════════════════
-- GAP 1: Dual-Ledger Consumption — Replenishment Pulls
-- ════════════════════════════════════════════════════════════════
-- Central = separate stock model: dept consumption does NOT deduct central
-- directly. Instead, when dept stock drops below its effective par, a
-- replenishment PULL (transfer request) is auto-generated from central.
-- This avoids double-counting while keeping central informed of demand.
-- ════════════════════════════════════════════════════════════════

CREATE TABLE IF NOT EXISTS public.uinv_replenishment_pulls (
  id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
  property_id uuid,
  pull_number text NOT NULL,
  -- The department store that needs stock
  dept_store_id text NOT NULL REFERENCES public.uinv_stores(id) ON DELETE CASCADE,
  -- The central store that will supply (default UINV-ST-MAIN)
  source_store_id text NOT NULL DEFAULT 'UINV-ST-MAIN' REFERENCES public.uinv_stores(id) ON DELETE CASCADE,
  item_id text NOT NULL REFERENCES public.uinv_items(id) ON DELETE CASCADE,
  -- Quantity requested to bring dept back up to par
  quantity_requested numeric(12,3) NOT NULL DEFAULT 0,
  -- Quantity actually shipped (filled by transfer)
  quantity_shipped numeric(12,3) NOT NULL DEFAULT 0,
  -- Trigger: 'auto' (generated by scan) or 'manual'
  trigger_type text NOT NULL DEFAULT 'auto',
  -- Status: Pending → Approved → Converted to Transfer → Fulfilled / Rejected
  status text NOT NULL DEFAULT 'Pending'
    CHECK (status IN ('Pending','Approved','Converted to Transfer','Fulfilled','Rejected','Cancelled')),
  -- The transfer created when this pull is fulfilled
  transfer_id text REFERENCES public.uinv_transfers(id) ON DELETE SET NULL,
  -- Why this pull was generated (e.g. "Stock 5.0 below par 20.0")
  reason text,
  -- Stock level at time of generation
  stock_at_generation numeric(12,3),
  par_at_generation numeric(12,3),
  approved_by text,
  approved_at timestamptz,
  rejected_by text,
  rejected_at timestamptz,
  rejection_reason text,
  created_by text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (pull_number)
);

CREATE INDEX IF NOT EXISTS idx_uinv_repl_pulls_dept
  ON public.uinv_replenishment_pulls(dept_store_id);
CREATE INDEX IF NOT EXISTS idx_uinv_repl_pulls_status
  ON public.uinv_replenishment_pulls(status);
CREATE INDEX IF NOT EXISTS idx_uinv_repl_pulls_item
  ON public.uinv_replenishment_pulls(item_id);

ALTER TABLE public.uinv_replenishment_pulls ENABLE ROW LEVEL SECURITY;
CREATE POLICY "authenticated can CRUD uinv_replenishment_pulls"
  ON public.uinv_replenishment_pulls FOR ALL TO authenticated
  USING (true) WITH CHECK (true);
CREATE POLICY "service_role all uinv_replenishment_pulls"
  ON public.uinv_replenishment_pulls FOR ALL TO service_role
  USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.uinv_replenishment_pulls TO authenticated;

-- ════════════════════════════════════════════════════════════════
-- GAP 2: Manual Par Overrides (temporary tier with auto-revert)
-- ════════════════════════════════════════════════════════════════
-- Three-tier par resolution:
--   1. Manual override (temporary, with optional expiry) — highest priority
--   2. Dynamic par (from uinv_consumption_stats) — medium priority
--   3. Standard par (uinv_items.par_level / stock_balances.replenish_max) — fallback
-- ════════════════════════════════════════════════════════════════

CREATE TABLE IF NOT EXISTS public.uinv_manual_par_overrides (
  id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
  property_id uuid,
  store_id text REFERENCES public.uinv_stores(id) ON DELETE CASCADE,
  item_id text NOT NULL REFERENCES public.uinv_items(id) ON DELETE CASCADE,
  -- The manual par values (override)
  manual_par_level numeric(12,3) NOT NULL DEFAULT 0,
  manual_replenish_min numeric(12,3) NOT NULL DEFAULT 0,
  manual_replenish_max numeric(12,3) NOT NULL DEFAULT 0,
  -- Reason for the override (e.g. "Banquet event on 2026-09-15")
  reason text,
  -- Optional expiry — when this override auto-reverts
  effective_from timestamptz NOT NULL DEFAULT now(),
  effective_until timestamptz,
  -- Whether this override is active
  is_active boolean NOT NULL DEFAULT true,
  -- Who created/approved it
  created_by text,
  approved_by text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_uinv_manual_par_store
  ON public.uinv_manual_par_overrides(store_id);
CREATE INDEX IF NOT EXISTS idx_uinv_manual_par_item
  ON public.uinv_manual_par_overrides(item_id);
CREATE INDEX IF NOT EXISTS idx_uinv_manual_par_active
  ON public.uinv_manual_par_overrides(is_active);

ALTER TABLE public.uinv_manual_par_overrides ENABLE ROW LEVEL SECURITY;
CREATE POLICY "authenticated can CRUD uinv_manual_par_overrides"
  ON public.uinv_manual_par_overrides FOR ALL TO authenticated
  USING (true) WITH CHECK (true);
CREATE POLICY "service_role all uinv_manual_par_overrides"
  ON public.uinv_manual_par_overrides FOR ALL TO service_role
  USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.uinv_manual_par_overrides TO authenticated;

