-- Journal posting log — prevents duplicate postings from inventory movements
CREATE TABLE IF NOT EXISTS public.uinv_journal_posting_log (
  id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
  -- The inventory movement that triggered the posting
  source_entity text NOT NULL,  -- 'uinv_stock_ledger', 'uinv_waste', 'uinv_adjustments'
  source_id text NOT NULL,      -- the ledger/waste/adjustment row id
  -- The journal entry created
  journal_id text NOT NULL REFERENCES public.journal_entries(id) ON DELETE CASCADE,
  -- Posting type: 'COGS', 'Inventory Valuation', 'Shrinkage', 'Receipt', 'Transfer'
  posting_type text NOT NULL,
  amount numeric(18,2) NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (source_entity, source_id)
);

CREATE INDEX IF NOT EXISTS idx_uinv_journal_posting_source
  ON public.uinv_journal_posting_log(source_entity, source_id);

ALTER TABLE public.uinv_journal_posting_log ENABLE ROW LEVEL SECURITY;
