-- ════════════════════════════════════════════════════════════════
-- GAP 5: Inter-Departmental Stock Borrowing
-- ════════════════════════════════════════════════════════════════
-- Temporary stock loans between departments with approval workflow
-- and mandatory return. Distinct from permanent transfers.
-- ════════════════════════════════════════════════════════════════

CREATE SEQUENCE IF NOT EXISTS public.uinv_dept_borrows_seq START 1;

CREATE TABLE IF NOT EXISTS public.uinv_dept_borrows (
  id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
  property_id uuid,
  borrow_number text NOT NULL DEFAULT 'BRW-' || to_char(now(), 'YYYY') || '-' || lpad(nextval('public.uinv_dept_borrows_seq')::text, 6, '0'),
  -- The department store borrowing the stock
  borrowing_store_id text NOT NULL REFERENCES public.uinv_stores(id) ON DELETE CASCADE,
  -- The department store lending the stock
  lending_store_id text NOT NULL REFERENCES public.uinv_stores(id) ON DELETE CASCADE,
  item_id text NOT NULL REFERENCES public.uinv_items(id) ON DELETE CASCADE,
  quantity_borrowed numeric(12,3) NOT NULL DEFAULT 0,
  -- Quantity returned (filled on return)
  quantity_returned numeric(12,3) NOT NULL DEFAULT 0,
  -- Expected return date
  expected_return_date date NOT NULL,
  actual_return_date date,
  -- Status: Requested → Approved → Dispatched → Received → Returned / Overdue / Rejected
  status text NOT NULL DEFAULT 'Requested'
    CHECK (status IN ('Requested','Approved','Rejected','Dispatched','Received','Partially Returned','Returned','Overdue','Cancelled')),
  -- Purpose / reason for borrowing
  purpose text,
  -- Approval workflow
  requested_by text,
  requested_at timestamptz NOT NULL DEFAULT now(),
  approved_by text,
  approved_at timestamptz,
  rejected_by text,
  rejected_at timestamptz,
  rejection_reason text,
  dispatched_by text,
  dispatched_at timestamptz,
  received_by text,
  received_at timestamptz,
  returned_by text,
  returned_at timestamptz,
  -- The transfer created for the borrow (dispatch)
  outbound_transfer_id text REFERENCES public.uinv_transfers(id) ON DELETE SET NULL,
  -- The transfer created for the return
  return_transfer_id text REFERENCES public.uinv_transfers(id) ON DELETE SET NULL,
  notes text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (borrow_number)
);

CREATE INDEX IF NOT EXISTS idx_uinv_borrows_borrowing
  ON public.uinv_dept_borrows(borrowing_store_id);
CREATE INDEX IF NOT EXISTS idx_uinv_borrows_lending
  ON public.uinv_dept_borrows(lending_store_id);
CREATE INDEX IF NOT EXISTS idx_uinv_borrows_status
  ON public.uinv_dept_borrows(status);
CREATE INDEX IF NOT EXISTS idx_uinv_borrows_item
  ON public.uinv_dept_borrows(item_id);

ALTER TABLE public.uinv_dept_borrows ENABLE ROW LEVEL SECURITY;
CREATE POLICY "authenticated can CRUD uinv_dept_borrows"
  ON public.uinv_dept_borrows FOR ALL TO authenticated
  USING (true) WITH CHECK (true);
CREATE POLICY "service_role all uinv_dept_borrows"
  ON public.uinv_dept_borrows FOR ALL TO service_role
  USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.uinv_dept_borrows TO authenticated;

