-- GAP 6: POS → Unified Inventory Linkage Columns
-- ════════════════════════════════════════════════════════════════
-- Add explicit linkage from pos_outlets and ingredients to uinv_*.
-- ════════════════════════════════════════════════════════════════

-- pos_outlets → unified store (POS uses pos_outlets, not outlets)
ALTER TABLE public.pos_outlets
  ADD COLUMN IF NOT EXISTS default_store_id text REFERENCES public.uinv_stores(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS idx_pos_outlets_default_store_id
  ON public.pos_outlets(default_store_id);

-- ingredients → unified item (for recipe-mode BOM deduction)
ALTER TABLE public.ingredients
  ADD COLUMN IF NOT EXISTS uinv_item_id text REFERENCES public.uinv_items(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS idx_ingredients_uinv_item_id
  ON public.ingredients(uinv_item_id);

-- Backfill pos_outlets.default_store_id from outlet name/type
UPDATE public.pos_outlets
  SET default_store_id = 'UINV-ST-BEV'
  WHERE default_store_id IS NULL
    AND (name ILIKE '%bar%' OR name ILIKE '%bev%' OR name ILIKE '%lounge%' OR name ILIKE '%minibar%');

UPDATE public.pos_outlets
  SET default_store_id = 'UINV-ST-FOOD'
  WHERE default_store_id IS NULL
    AND (name ILIKE '%restaurant%' OR name ILIKE '%kitchen%' OR name ILIKE '%room service%' OR name ILIKE '%banquet%');

-- Backfill ingredients.uinv_item_id by case-insensitive name match
UPDATE public.ingredients ing
  SET uinv_item_id = ui.id
  FROM public.uinv_items ui
  WHERE ing.uinv_item_id IS NULL
    AND lower(ing.name) = lower(ui.item_name)
    AND ui.category = 'Food & Beverage';

-- ════════════════════════════════════════════════════════════════
-- FUNCTION: effective_par_level(p_item_id, p_store_id)
-- Resolves the three-tier par: manual override > dynamic > standard
-- ════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.effective_par_level(
  p_item_id text,
  p_store_id text
)
RETURNS TABLE (
  par_level numeric,
  replenish_min numeric,
  replenish_max numeric,
  source text  -- 'manual', 'dynamic', 'standard'
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_manual RECORD;
  v_dynamic RECORD;
  v_standard_par numeric;
  v_standard_min numeric;
  v_standard_max numeric;
BEGIN
  -- 1. Check for active manual override (highest priority)
  SELECT manual_par_level, manual_replenish_min, manual_replenish_max
  INTO v_manual
  FROM public.uinv_manual_par_overrides
  WHERE item_id = p_item_id
    AND (store_id = p_store_id OR store_id IS NULL)
    AND is_active = true
    AND effective_from <= now()
    AND (effective_until IS NULL OR effective_until >= now())
  ORDER BY store_id NULLS LAST, created_at DESC
  LIMIT 1;

  IF FOUND THEN
    par_level := v_manual.manual_par_level;
    replenish_min := v_manual.manual_replenish_min;
    replenish_max := v_manual.manual_replenish_max;
    source := 'manual';
    RETURN NEXT;
    RETURN;
  END IF;

  -- 2. Check for dynamic par from consumption stats (30-day lookback)
  SELECT dynamic_par_level, dynamic_replenish_min, dynamic_replenish_max
  INTO v_dynamic
  FROM public.uinv_consumption_stats
  WHERE item_id = p_item_id
    AND store_id = p_store_id
    AND lookback_days = 30
  ORDER BY calculated_at DESC
  LIMIT 1;

  IF FOUND AND v_dynamic.dynamic_par_level > 0 THEN
    par_level := v_dynamic.dynamic_par_level;
    replenish_min := v_dynamic.dynamic_replenish_min;
    replenish_max := v_dynamic.dynamic_replenish_max;
    source := 'dynamic';
    RETURN NEXT;
    RETURN;
  END IF;

  -- 3. Fallback to standard par from stock balances + item master
  SELECT
    COALESCE(sb.replenish_max, i.par_level),
    COALESCE(sb.replenish_min, i.reorder_point),
    COALESCE(sb.replenish_max, i.max_stock, i.par_level)
  INTO v_standard_par, v_standard_min, v_standard_max
  FROM public.uinv_items i
  LEFT JOIN public.uinv_stock_balances sb
    ON sb.item_id = i.id AND sb.store_id = p_store_id
  WHERE i.id = p_item_id
  LIMIT 1;

  par_level := COALESCE(v_standard_par, 0);
  replenish_min := COALESCE(v_standard_min, 0);
  replenish_max := COALESCE(v_standard_max, 0);
  source := 'standard';
  RETURN NEXT;
  RETURN;
END;
$$;

GRANT EXECUTE ON FUNCTION public.effective_par_level(text, text) TO authenticated;

-- ════════════════════════════════════════════════════════════════
-- FUNCTION: generate_replenishment_pulls_for_dept(p_dept_store_id)
-- Gap 1: Scans a department store for items below effective par and
-- auto-generates replenishment pull requests from central.
-- Returns the list of pulls created.
-- ════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.generate_replenishment_pulls_for_dept(
  p_dept_store_id text,
  p_property_id uuid DEFAULT NULL
)
RETURNS TABLE (
  pull_id text,
  pull_number text,
  item_id text,
  item_name text,
  quantity_requested numeric,
  stock_level numeric,
  par_level numeric,
  source text
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_pull_number text;
  v_seq int;
  v_eff_par numeric;
  v_eff_min numeric;
  v_eff_max numeric;
  v_eff_source text;
  v_qty_needed numeric;
  v_pull_id text;
  r RECORD;
BEGIN
  -- Generate pull number sequence
  SELECT COALESCE(MAX(CAST(SUBSTRING(rp.pull_number FROM 'RP-\\d{4}-(\\d{6})') AS int)), 0) + 1
  INTO v_seq
  FROM public.uinv_replenishment_pulls rp
  WHERE rp.pull_number LIKE 'RP-' || to_char(now(), 'YYYY') || '-%';
  v_pull_number := 'RP-' || to_char(now(), 'YYYY') || '-' || lpad(v_seq::text, 6, '0');

  -- Scan dept store balances for items below effective par
  FOR r IN
    SELECT sb.id, sb.item_id, sb.on_hand, sb.property_id, i.item_name
    FROM public.uinv_stock_balances sb
    JOIN public.uinv_items i ON i.id = sb.item_id
    WHERE sb.store_id = p_dept_store_id
      AND i.is_active = true
      AND (p_property_id IS NULL OR sb.property_id = p_property_id)
  LOOP
    -- Get effective par (manual > dynamic > standard)
    SELECT * FROM public.effective_par_level(r.item_id, p_dept_store_id)
    INTO v_eff_par, v_eff_min, v_eff_max, v_eff_source;

    -- If on_hand is below effective replenish_min, generate a pull
    IF r.on_hand < v_eff_min AND v_eff_max > 0 THEN
      v_qty_needed := v_eff_max - r.on_hand;

      -- Skip if there's already a pending pull for this item+store
      IF EXISTS (
        SELECT 1 FROM public.uinv_replenishment_pulls rp2
        WHERE rp2.dept_store_id = p_dept_store_id
          AND rp2.item_id = r.item_id
          AND rp2.status IN ('Pending','Approved')
      ) THEN
        CONTINUE;
      END IF;

      v_pull_id := gen_random_uuid()::text;
      v_pull_number := 'RP-' || to_char(now(), 'YYYY') || '-' || lpad(v_seq::text, 6, '0');
      v_seq := v_seq + 1;

      INSERT INTO public.uinv_replenishment_pulls (
        id, property_id, pull_number, dept_store_id, source_store_id,
        item_id, quantity_requested, trigger_type, status, reason,
        stock_at_generation, par_at_generation, created_by
      ) VALUES (
        v_pull_id, COALESCE(r.property_id, p_property_id), v_pull_number,
        p_dept_store_id, 'UINV-ST-MAIN', r.item_id, v_qty_needed,
        'auto', 'Pending',
        'Stock ' || r.on_hand || ' below ' || v_eff_source || ' par min ' || v_eff_min,
        r.on_hand, v_eff_max, 'system'
      );

      pull_id := v_pull_id;
      pull_number := v_pull_number;
      item_id := r.item_id;
      item_name := r.item_name;
      quantity_requested := v_qty_needed;
      stock_level := r.on_hand;
      par_level := v_eff_max;
      source := v_eff_source;
      RETURN NEXT;
    END IF;
  END LOOP;

  RETURN;
END;
$$;

GRANT EXECUTE ON FUNCTION public.generate_replenishment_pulls_for_dept(text, uuid) TO authenticated;

-- ════════════════════════════════════════════════════════════════
-- FUNCTION: generate_procurement_requisitions_from_low_stock()
-- Gap 3: Scans UINV-ST-MAIN for items below reorder point and
-- auto-creates procurement requisitions.
-- ════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.generate_procurement_requisition_from_low_stock(
  p_property_id uuid DEFAULT NULL,
  p_created_by text DEFAULT 'system'
)
RETURNS TABLE (
  requisition_id text,
  pr_number text,
  item_count int,
  estimated_total numeric
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_pr_number text;
  v_seq int;
  v_req_id text;
  v_estimated_total numeric;
  v_line_count int;
  v_required_date date;
  r RECORD;
BEGIN
  v_required_date := CURRENT_DATE + 7;  -- default required date = 7 days out

  -- Calculate starting sequence ONCE before the loop
  SELECT COALESCE(MAX(CAST(SUBSTRING(pr2.pr_number FROM 'PR-\\d{4}-(\\d{6})') AS int)), 0) + 1
  INTO v_seq
  FROM public.proc_requisitions pr2
  WHERE pr2.pr_number LIKE 'PR-' || to_char(now(), 'YYYY') || '-%';

  -- Scan central warehouse for low stock
  FOR r IN
    SELECT sb.item_id, sb.on_hand, i.item_name, i.item_code, i.category,
           i.unit_of_measure, i.reorder_point, i.min_stock, i.max_stock,
           i.last_cost, sb.property_id
    FROM public.uinv_stock_balances sb
    JOIN public.uinv_items i ON i.id = sb.item_id
    WHERE sb.store_id = 'UINV-ST-MAIN'
      AND i.is_active = true
      AND sb.on_hand <= COALESCE(NULLIF(i.reorder_point, 0), i.min_stock)
      AND (p_property_id IS NULL OR sb.property_id = p_property_id)
      -- Skip items that already have an open procurement requisition
      AND NOT EXISTS (
        SELECT 1 FROM public.proc_requisitions pr
        JOIN public.proc_requisition_lines prl ON prl.requisition_id = pr.id
        WHERE pr.source_system = 'inventory'
          AND pr.status IN ('Draft','Submitted','Under Review','Approved','Sourcing')
          AND prl.item_code = i.item_code
      )
  LOOP
    v_pr_number := 'PR-' || to_char(now(), 'YYYY') || '-' || lpad(v_seq::text, 6, '0');
    v_req_id := gen_random_uuid()::text;
    v_seq := v_seq + 1;

    -- Quantity to order = max_stock - on_hand (fill to max)
    DECLARE
      v_order_qty numeric;
    BEGIN
      v_order_qty := COALESCE(NULLIF(r.max_stock, 0), r.reorder_point * 2, r.min_stock * 2) - r.on_hand;
      IF v_order_qty <= 0 THEN
        v_order_qty := r.reorder_point;
      END IF;

      v_estimated_total := v_order_qty * COALESCE(r.last_cost, 0);

      -- Insert requisition header
      INSERT INTO public.proc_requisitions (
        id, pr_number, property_id, department, requester,
        required_date, priority, purpose, status, estimated_total,
        source_system, source_ref, created_by
      ) VALUES (
        v_req_id, v_pr_number, COALESCE(r.property_id, p_property_id),
        'Inventory', 'Inventory System (Auto)', v_required_date,
        'High', 'Auto-generated from low central warehouse stock',
        'Submitted', v_estimated_total,
        'inventory', 'UINV-ST-MAIN low stock: ' || r.item_code, p_created_by
      );

      -- Insert requisition line
      INSERT INTO public.proc_requisition_lines (
        requisition_id, line_number, item_code, item_name,
        category, quantity, unit_of_measure,
        estimated_unit_price, estimated_total, required_date
      ) VALUES (
        v_req_id, 1, r.item_code, r.item_name,
        r.category, v_order_qty, r.unit_of_measure,
        COALESCE(r.last_cost, 0), v_estimated_total, v_required_date
      );

      requisition_id := v_req_id;
      pr_number := v_pr_number;
      item_count := 1;
      estimated_total := v_estimated_total;
      RETURN NEXT;
    END;
  END LOOP;

  RETURN;
END;
$$;

GRANT EXECUTE ON FUNCTION public.generate_procurement_requisition_from_low_stock(uuid, text) TO authenticated;

-- ════════════════════════════════════════════════════════════════
-- FUNCTION: post_inventory_journal()
-- Gap 4: Posts a finance journal entry for an inventory movement.
-- Supports COGS (consumption), Inventory Valuation (receipts), and
-- Shrinkage (waste/adjustments).
-- ════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.post_inventory_journal(
  p_source_entity text,    -- 'uinv_stock_ledger', 'uinv_waste', 'uinv_adjustments'
  p_source_id text,        -- the row id in the source table
  p_posting_type text,     -- 'COGS', 'Inventory Valuation', 'Shrinkage'
  p_amount numeric,        -- total amount (debit = credit)
  p_description text,
  p_department text DEFAULT NULL,
  p_property_id uuid DEFAULT NULL,
  p_reference text DEFAULT NULL,
  p_created_by text DEFAULT 'system'
)
RETURNS text  -- the journal_id
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_journal_id text;
  v_period text;
  v_inv_account text;
  v_cogs_account text;
  v_shrinkage_account text;
  v_dept_category text;
  v_abs_amount numeric;
  v_ref text;
BEGIN
  -- Prevent duplicate postings
  IF EXISTS (
    SELECT 1 FROM public.uinv_journal_posting_log
    WHERE source_entity = p_source_entity AND source_id = p_source_id
  ) THEN
    RETURN NULL;
  END IF;

  -- Skip zero-amount postings
  IF p_amount = 0 THEN
    RETURN NULL;
  END IF;

  -- Determine the period (YYYY-MM)
  v_period := to_char(now(), 'YYYY-MM');

  -- Resolve GL accounts based on department/category
  -- Default inventory account
  v_inv_account := '1190';  -- Inventory - Central Warehouse

  -- If department is provided, use department-specific inventory account
  IF p_department ILIKE '%food%' OR p_department ILIKE '%kitchen%' THEN
    v_inv_account := '1100';
    v_cogs_account := '3100';
    v_shrinkage_account := '8410';
  ELSIF p_department ILIKE '%bev%' OR p_department ILIKE '%bar%' THEN
    v_inv_account := '1110';
    v_cogs_account := '3200';
    v_shrinkage_account := '8420';
  ELSIF p_department ILIKE '%house%' OR p_department ILIKE '%hk%' THEN
    v_inv_account := '1120';
    v_cogs_account := '3300';
    v_shrinkage_account := '8430';
  ELSIF p_department ILIKE '%eng%' OR p_department ILIKE '%maintenance%' THEN
    v_inv_account := '1130';
    v_cogs_account := '3400';
    v_shrinkage_account := '8440';
  ELSIF p_department ILIKE '%linen%' THEN
    v_inv_account := '1150';
    v_cogs_account := '3300';
    v_shrinkage_account := '8430';
  ELSE
    v_inv_account := '1140';
    v_cogs_account := '3500';
    v_shrinkage_account := '8400';
  END IF;

  v_journal_id := 'je_inv_' || to_char(now(), 'YYYYMMDDHH24MISS') || '_' || md5(p_source_id)::text;
  v_abs_amount := abs(p_amount);
  v_ref := COALESCE(NULLIF(p_reference, ''), p_source_entity || ':' || p_source_id);

  -- Create journal entry header
  INSERT INTO public.journal_entries (
    id, entry_date, period, source, reference, description,
    status, total_debit, total_credit, department, property_id, created_by
  ) VALUES (
    v_journal_id, CURRENT_DATE, v_period, 'System',
    v_ref, p_description, 'Draft', v_abs_amount, v_abs_amount, p_department, p_property_id, p_created_by
  );

  -- Create journal lines based on posting type
  IF p_posting_type = 'COGS' THEN
    -- COGS: Debit COGS expense, Credit Inventory asset
    INSERT INTO public.journal_lines (id, journal_entry_id, account_code, account_name, description, debit, credit, line_number)
    VALUES
      (gen_random_uuid()::text, v_journal_id, v_cogs_account,
       (SELECT name FROM public.usali_chart_of_accounts WHERE code = v_cogs_account),
       'COGS - ' || p_description, v_abs_amount, 0, 1),
      (gen_random_uuid()::text, v_journal_id, v_inv_account,
       (SELECT name FROM public.usali_chart_of_accounts WHERE code = v_inv_account),
       'Inventory consumed - ' || p_description, 0, v_abs_amount, 2);

  ELSIF p_posting_type = 'Inventory Valuation' THEN
    -- Receipt: Debit Inventory asset, Credit Accounts Payable (or Inventory Clearing)
    -- For simplicity, credit a generic inventory clearing (use 1190 contra or AP)
    -- We'll use 1190 as both sides would be wrong; use a liability account.
    -- Since no AP control account is guaranteed, we post as Inventory Debit / Inventory Credit
    -- for transfers, and for receipts we Debit Inventory / Credit AP (2190 if exists)
    DECLARE
      v_ap_account text;
    BEGIN
      SELECT code INTO v_ap_account FROM public.usali_chart_of_accounts
      WHERE account_type = 'Liability' AND name ILIKE '%accounts payable%' LIMIT 1;
      IF v_ap_account IS NULL THEN
        v_ap_account := '2100';  -- common AP code fallback
        -- If 2100 doesn't exist, use the inventory account as a contra (not ideal but safe)
        IF NOT EXISTS (SELECT 1 FROM public.usali_chart_of_accounts WHERE code = '2100') THEN
          v_ap_account := v_inv_account;
        END IF;
      END IF;

      INSERT INTO public.journal_lines (id, journal_entry_id, account_code, account_name, description, debit, credit, line_number)
      VALUES
        (gen_random_uuid()::text, v_journal_id, v_inv_account,
         (SELECT name FROM public.usali_chart_of_accounts WHERE code = v_inv_account),
         'Inventory received - ' || p_description, v_abs_amount, 0, 1),
        (gen_random_uuid()::text, v_journal_id, v_ap_account,
         (SELECT name FROM public.usali_chart_of_accounts WHERE code = v_ap_account),
         'AP for goods received - ' || p_description, 0, v_abs_amount, 2);
    END;

  ELSIF p_posting_type = 'Shrinkage' THEN
    -- Shrinkage/Waste: Debit Shrinkage expense, Credit Inventory asset
    INSERT INTO public.journal_lines (id, journal_entry_id, account_code, account_name, description, debit, credit, line_number)
    VALUES
      (gen_random_uuid()::text, v_journal_id, v_shrinkage_account,
       (SELECT name FROM public.usali_chart_of_accounts WHERE code = v_shrinkage_account),
       'Inventory shrinkage/waste - ' || p_description, v_abs_amount, 0, 1),
      (gen_random_uuid()::text, v_journal_id, v_inv_account,
       (SELECT name FROM public.usali_chart_of_accounts WHERE code = v_inv_account),
       'Inventory written off - ' || p_description, 0, v_abs_amount, 2);

  ELSIF p_posting_type = 'Variance' THEN
    -- Variance: handles both positive (gain) and negative (loss) adjustments
    IF p_amount > 0 THEN
      -- Positive adjustment (gain): Debit Inventory, Credit Variance
      INSERT INTO public.journal_lines (id, journal_entry_id, account_code, account_name, description, debit, credit, line_number)
      VALUES
        (gen_random_uuid()::text, v_journal_id, v_inv_account,
         (SELECT name FROM public.usali_chart_of_accounts WHERE code = v_inv_account),
         'Inventory gain - ' || p_description, p_amount, 0, 1),
        (gen_random_uuid()::text, v_journal_id, '8450',
         (SELECT name FROM public.usali_chart_of_accounts WHERE code = '8450'),
         'Inventory variance credit - ' || p_description, 0, p_amount, 2);
    ELSE
      -- Negative adjustment (loss): Debit Variance, Credit Inventory
      INSERT INTO public.journal_lines (id, journal_entry_id, account_code, account_name, description, debit, credit, line_number)
      VALUES
        (gen_random_uuid()::text, v_journal_id, '8450',
         (SELECT name FROM public.usali_chart_of_accounts WHERE code = '8450'),
         'Inventory variance debit - ' || p_description, abs(p_amount), 0, 1),
        (gen_random_uuid()::text, v_journal_id, v_inv_account,
         (SELECT name FROM public.usali_chart_of_accounts WHERE code = v_inv_account),
         'Inventory written off - ' || p_description, 0, abs(p_amount), 2);
    END IF;
  END IF;

  -- Log the posting
  INSERT INTO public.uinv_journal_posting_log (source_entity, source_id, journal_id, posting_type, amount)
  VALUES (p_source_entity, p_source_id, v_journal_id, p_posting_type, p_amount);

  RETURN v_journal_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.post_inventory_journal(text, text, text, numeric, text, text, uuid, text, text) TO authenticated;

-- ════════════════════════════════════════════════════════════════
-- GAP 6: Replace deduct_outlet_inventory() with corrected + dual-write version
-- ════════════════════════════════════════════════════════════════
-- The original function (migration 175) referenced non-existent fn_* tables
-- and used wrong column names. This replacement:
--   1. Uses real tables: recipes, recipe_lines, ingredients, stock_transactions
--   2. Fixes column names: inventory_items.current_quantity (not current_stock)
--   3. Dual-writes to uinv_stock_balances + uinv_stock_ledger
-- ════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.deduct_outlet_inventory(
  p_outlet_id UUID,
  p_line_items JSONB,
  p_inventory_mode TEXT,
  p_reference_doc TEXT DEFAULT NULL,
  p_reference_type TEXT DEFAULT 'pos_sale'
)
RETURNS TABLE (
  ingredient_id TEXT,
  ingredient_name TEXT,
  quantity_deducted NUMERIC,
  unit TEXT,
  status TEXT
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_line JSONB;
  v_item_id TEXT;
  v_qty NUMERIC;
  v_menu_item_id TEXT;
  v_recipe RECORD;
  v_recipe_line RECORD;
  v_uinv_item_id TEXT;
  v_store_id TEXT;
  v_balance RECORD;
  v_new_on_hand NUMERIC;
  v_unit_cost NUMERIC;
  v_outlet RECORD;
BEGIN
  -- Resolve the outlet's default unified store
  SELECT default_store_id, name INTO v_outlet
  FROM public.pos_outlets WHERE id = p_outlet_id LIMIT 1;

  v_store_id := COALESCE(v_outlet.default_store_id, 'UINV-ST-FOOD');

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_line_items)
  LOOP
    v_item_id := v_line->>'item_id';
    v_qty := COALESCE((v_line->>'quantity')::numeric, 0);
    v_menu_item_id := v_line->>'menu_item_id';

    IF v_qty <= 0 THEN CONTINUE; END IF;

    IF p_inventory_mode = 'recipe' THEN
      -- Recipe mode: deduct BOM components via recipes/recipe_lines/ingredients
      FOR v_recipe IN
        SELECT r.id FROM public.recipes r
        WHERE r.menu_item_id = v_menu_item_id
        LIMIT 1
      LOOP
        FOR v_recipe_line IN
          SELECT rl.ingredient_id, rl.quantity, rl.unit, i.name, i.current_cost,
                 i.uinv_item_id
          FROM public.recipe_lines rl
          JOIN public.ingredients i ON i.id = rl.ingredient_id
          WHERE rl.recipe_id = v_recipe.id
        LOOP
          DECLARE
            v_deduct_qty NUMERIC := v_recipe_line.quantity * v_qty;
          BEGIN
            -- 1. Legacy write: stock_transactions
            INSERT INTO public.stock_transactions (
              ingredient_id, transaction_type, quantity, unit,
              cost_per_unit, total_value, date,
              reference_doc, reference_type, notes
            ) VALUES (
              v_recipe_line.ingredient_id, 'POSDepletion',
              v_deduct_qty, v_recipe_line.unit,
              COALESCE(v_recipe_line.current_cost, 0),
              COALESCE(v_recipe_line.current_cost, 0) * v_deduct_qty,
              NOW(), p_reference_doc, p_reference_type,
              'Auto-deducted from POS sale (recipe mode)'
            );

            -- 2. Unified dual-write: uinv_stock_balances + uinv_stock_ledger
            v_uinv_item_id := v_recipe_line.uinv_item_id;
            -- Fallback: resolve by name match
            IF v_uinv_item_id IS NULL THEN
              SELECT ui.id INTO v_uinv_item_id
              FROM public.uinv_items ui
              WHERE lower(ui.item_name) = lower(v_recipe_line.name)
                AND ui.category = 'Food & Beverage'
              LIMIT 1;
            END IF;

            IF v_uinv_item_id IS NOT NULL THEN
              -- Find or create balance row
              SELECT id, on_hand, unit_cost INTO v_balance
              FROM public.uinv_stock_balances
              WHERE item_id = v_uinv_item_id AND store_id = v_store_id
              ORDER BY updated_at DESC LIMIT 1;

              v_unit_cost := COALESCE(v_recipe_line.current_cost, 0);

              IF v_balance IS NOT NULL THEN
                v_new_on_hand := GREATEST(0, COALESCE(v_balance.on_hand, 0) - v_deduct_qty);
                UPDATE public.uinv_stock_balances
                  SET on_hand = v_new_on_hand,
                      last_movement_date = NOW(),
                      updated_at = NOW()
                  WHERE id = v_balance.id;
              ELSE
                v_new_on_hand := 0;
                INSERT INTO public.uinv_stock_balances (
                  id, item_id, store_id, on_hand, status, unit_cost,
                  last_movement_date
                ) VALUES (
                  gen_random_uuid()::text, v_uinv_item_id, v_store_id,
                  0, 'Available', v_unit_cost, NOW()
                );
              END IF;

              -- Append to unified ledger
              INSERT INTO public.uinv_stock_ledger (
                item_id, store_id, transaction_type, reference,
                quantity_in, quantity_out, balance, unit_cost, value,
                performed_by, reason, transaction_date
              ) VALUES (
                v_uinv_item_id, v_store_id, 'Consumption', p_reference_doc,
                0, v_deduct_qty, v_new_on_hand, v_unit_cost,
                v_deduct_qty * v_unit_cost, 'pos_system',
                'POS sale (recipe mode) - ' || v_recipe_line.name, NOW()
              );
            END IF;

            RETURN QUERY SELECT
              v_recipe_line.ingredient_id::text,
              v_recipe_line.name,
              v_deduct_qty,
              v_recipe_line.unit,
              'deducted';
          END;
        END LOOP;
      END LOOP;

    ELSE
      -- SKU mode: deduct direct stock from inventory_items (legacy)
      -- AND dual-write to uinv_* if linked
      DECLARE
        v_inv_item RECORD;
      BEGIN
        SELECT id, name, current_quantity, unit_cost, uinv_item_id, item_code, sku
        INTO v_inv_item
        FROM public.inventory_items
        WHERE id = v_item_id OR item_code = v_item_id OR sku = v_item_id
        LIMIT 1;

        IF v_inv_item IS NOT NULL THEN
          -- 1. Legacy write
          UPDATE public.inventory_items
            SET current_quantity = GREATEST(0, current_quantity - v_qty),
                updated_at = NOW()
            WHERE id = v_inv_item.id;

          -- 2. Unified dual-write
          v_uinv_item_id := v_inv_item.uinv_item_id;
          IF v_uinv_item_id IS NULL THEN
            -- Fallback: name match
            SELECT ui.id INTO v_uinv_item_id
            FROM public.uinv_items ui
            WHERE lower(ui.item_name) = lower(v_inv_item.name)
              AND ui.category = 'Food & Beverage'
            LIMIT 1;
          END IF;

          IF v_uinv_item_id IS NOT NULL THEN
            SELECT id, on_hand, unit_cost INTO v_balance
            FROM public.uinv_stock_balances
            WHERE item_id = v_uinv_item_id AND store_id = v_store_id
            ORDER BY updated_at DESC LIMIT 1;

            v_unit_cost := COALESCE(v_inv_item.unit_cost, 0);

            IF v_balance IS NOT NULL THEN
              v_new_on_hand := GREATEST(0, COALESCE(v_balance.on_hand, 0) - v_qty);
              UPDATE public.uinv_stock_balances
                SET on_hand = v_new_on_hand, last_movement_date = NOW(), updated_at = NOW()
                WHERE id = v_balance.id;
            ELSE
              v_new_on_hand := 0;
              INSERT INTO public.uinv_stock_balances (
                id, item_id, store_id, on_hand, status, unit_cost, last_movement_date
              ) VALUES (
                gen_random_uuid()::text, v_uinv_item_id, v_store_id,
                0, 'Available', v_unit_cost, NOW()
              );
            END IF;

            INSERT INTO public.uinv_stock_ledger (
              item_id, store_id, transaction_type, reference,
              quantity_in, quantity_out, balance, unit_cost, value,
              performed_by, reason, transaction_date
            ) VALUES (
              v_uinv_item_id, v_store_id, 'Consumption', p_reference_doc,
              0, v_qty, v_new_on_hand, v_unit_cost,
              v_qty * v_unit_cost, 'pos_system',
              'POS sale (SKU mode) - ' || v_inv_item.name, NOW()
            );
          END IF;

          RETURN QUERY SELECT
            v_inv_item.id,
            v_inv_item.name,
            v_qty,
            COALESCE(v_inv_item.unit_of_measure, 'units'),
            'deducted';
        ELSE
          RETURN QUERY SELECT v_item_id, v_item_id, v_qty, 'units', 'not_found';
        END IF;
      END;
    END IF;
  END LOOP;

  RETURN;
END;
$$;

GRANT EXECUTE ON FUNCTION public.deduct_outlet_inventory(uuid, jsonb, text, text, text) TO authenticated;

-- ════════════════════════════════════════════════════════════════
-- VERIFICATION
-- ════════════════════════════════════════════════════════════════
DO $$
BEGIN
  RAISE NOTICE 'Migration 373 complete: inventory system enhancements installed.';
  RAISE NOTICE 'Tables: uinv_replenishment_pulls, uinv_manual_par_overrides, uinv_journal_posting_log, uinv_dept_borrows';
  RAISE NOTICE 'Functions: effective_par_level(), generate_replenishment_pulls_for_dept(), generate_procurement_requisition_from_low_stock(), post_inventory_journal(), deduct_outlet_inventory() (replaced)';
  RAISE NOTICE 'GL accounts added: 1100-1150 (inventory assets), 8400-8450 (shrinkage), 3300-3500 (dept COGS)';
  RAISE NOTICE 'Linkage columns: pos_outlets.default_store_id, ingredients.uinv_item_id';
END $$;
